import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as a}from"./chunks/DIS.DdpTdGGD.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as o,a as n,b as l}from"./chunks/M-S-LCS11a.DEHuJb6u.js";import{_ as r,o as d,c as p,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Less Common Settings","description":"","frontmatter":{},"headers":[],"relativePath":"use/lesscommon.md","filePath":"use/lesscommon.md"}'),c={name:"use/lesscommon.md"};function h(g,i,u,b,v,y){return d(),p("div",null,[...i[0]||(i[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Settings<br>   Less Common settings</p></div><p>More xDrip settings are available in less common settings.<br> If you can&#39;t find the setting you&#39;re looking for, keep in mind you can use the search lens from the main <a href="./settings.html">settings</a> menu.</p><h3 id="extra-status-line" tabindex="-1">Extra Status Line <a class="header-anchor" href="#extra-status-line" aria-label="Permalink to &quot;Extra Status Line&quot;">​</a></h3><p>Top left of your main graph you can see the standard status line.<br> This menu allows you to add extra information in this area.</p><div class="admonition xdripitem"><p class="admonition-title">Extra Status Line</p><p> Options for the extra line</p></div><p>You need to enable the extra status line to add extra information.</p><div class="admonition xdripitem"><p class="admonition-title">Extra Status Line <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Additional text status</p></div><p>You can have selected statistics calculated over the last 24 hours. By default they&#39;re starting at midnight.</p><div class="admonition xdripitem"><p class="admonition-title">Sliding Window <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Use last 24 hours instead of time since midnight for statistics</p></div><p>There is a long list of available extra information you can display.<br> Only select those you really need to see every 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Average <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Today&#39;s average value</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c DCCT <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> A1c estimation in DCCT format (%)</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c IFCC <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> A1c estimation in IFCC format (mmol/mol)</p></div><div class="admonition xdripitem"><p class="admonition-title">In percentage <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Percentage of values in range</p></div><div class="admonition xdripitem"><p class="admonition-title">High percentage <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Percentage of values above range</p></div><div class="admonition xdripitem"><p class="admonition-title">Low percentage <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Percentage of values below range</p></div><div class="admonition xdripitem"><p class="admonition-title">Standard deviation <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show standard deviation of values</p></div><div class="admonition xdripitem"><p class="admonition-title">Total carbohydrate <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show treatment carbohydrate total</p></div><div class="admonition xdripitem"><p class="admonition-title">Total insulin <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show treatment insulin total</p></div><div class="admonition xdripitem"><p class="admonition-title">External status <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Display status from other apps like AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">Pump status <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Display pump status information if available</p></div><div class="admonition xdripitem"><p class="admonition-title">Carb/Insulin ratio <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show treatment Carb/Insulin ratio</p></div><div class="admonition xdripitem"><p class="admonition-title">Packet capture percentage <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Percentage of sensor readings received</p></div><div class="admonition xdripitem"><p class="admonition-title">Realtime packet capture percentage <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Percentage of sensor readings received in realtime (non-backfilled). Dex Native mode ONLY</p></div><div class="admonition xdripitem"><p class="admonition-title">Accuracy evaluation <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show calibration accuracy evaluation from last 3 days</p></div><div class="admonition xdripitem"><p class="admonition-title">Time <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> The current time</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration data (long) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Show slope and intercept in long form</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration data (short) <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show slope and intercept in short form</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration plugin <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show slope and glucose data from the active plugin</p></div><p>You can also add this extra information on your <a href="./mainUI.html#widget">widget</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Show on widget <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Also show the extra status line on the widget</p></div><h3 id="advanced-calibration" tabindex="-1"><a href="./../calibrate/advancedcal.html">Advanced Calibration</a> <a class="header-anchor" href="#advanced-calibration" aria-label="Permalink to &quot;[Advanced Calibration](../calibrate/advancedcal)&quot;">​</a></h3><p>See the dedicated section.</p><div class="admonition xdripitem"><p class="admonition-title">Advanced calibration</p><p> Extra options relating to calibrations</p></div><h3 id="bluetooth-settings" tabindex="-1"><a href="./bluetooth.html">Bluetooth Settings</a> <a class="header-anchor" href="#bluetooth-settings" aria-label="Permalink to &quot;[Bluetooth Settings](./bluetooth)&quot;">​</a></h3><p>See the dedicated section.</p><div class="admonition xdripitem"><p class="admonition-title">Bluetooth settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Advanced Bluetooth settings</p></div><h3 id="bluereader-settings" tabindex="-1">blueReader Settings <a class="header-anchor" href="#bluereader-settings" aria-label="Permalink to &quot;blueReader Settings&quot;">​</a></h3><p>Settings for the <a href="https://www.startnext.com/en/bluereader/wall" target="_blank" rel="noreferrer">pioneer</a> Libre bridge device from Sandra.</p><div class="admonition xdripitem"><p class="admonition-title">blueReader settings</p><p> Advanced blueReader settings</p></div><h3 id="advanced-settings-for-libre-2" tabindex="-1">Advanced Settings for Libre 2 <a class="header-anchor" href="#advanced-settings-for-libre-2" aria-label="Permalink to &quot;Advanced Settings for Libre 2&quot;">​</a></h3><p>Show additional information for Libre 2 sensors</p><div class="admonition xdripitem"><p class="admonition-title">Advanced settings for Libre 2</p></div><p>Display raw values on the <a href="./display.html#graph-settings">main graph</a></p><div class="admonition xdripitem"><p class="admonition-title">Show raw values in graph <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Switch on to show raw values in graph.</p></div><img src="'+o+'" style="zoom:75%;"><p>Show more information in status</p><div class="admonition xdripitem"><p class="admonition-title">Show sensor info in Status <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Switch on to show additional information in Status for Libre 2 sensor.</p></div><h3 id="aggressive-service-restarts" tabindex="-1">Aggressive Service Restarts <a class="header-anchor" href="#aggressive-service-restarts" aria-label="Permalink to &quot;Aggressive Service Restarts&quot;">​</a></h3><p>Enabling this provokes a <a href="./../troubleshoot/systemstatus.html#restart-collector-forget-device">collector restart</a> when detecting missing data. This can be useful if you have connection problems.</p><div class="admonition xdripitem"><p class="admonition-title">Aggressive service restarts <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Repeatedly restart the collection service at any hint of missing data. Enable only if you are getting data loss.</p></div><h3 id="interpret-raw-values" tabindex="-1">Interpret Raw Values <a class="header-anchor" href="#interpret-raw-values" aria-label="Permalink to &quot;Interpret Raw Values&quot;">​</a></h3><p>Display data when not available on the Dexcom receiver.</p><div class="admonition xdripitem"><p class="admonition-title">Interpret raw values <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> If using Share, xDrip will show values when they are normally hidden on the receiver.</p></div><h3 id="extra-logging-settings" tabindex="-1">Extra Logging Settings <a class="header-anchor" href="#extra-logging-settings" aria-label="Permalink to &quot;Extra Logging Settings&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Extra Logging Settings</p></div><p>These options are not used anymore.</p><div class="admonition xdripitem"><p class="admonition-title">Enable remote logging <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Store logs for troubleshooting <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Adding extra tags is useful for debugging as it will add specific traces in the log.</p><div class="admonition xdripitem"><p class="admonition-title">Extra tags for logging</p></div><p>You need to know what you want to debug and set the correct level. Make sure to put valid tags to avoid xDrip crashing.</p><img src="'+n+'" style="zoom:75%;"><h3 id="show-data-tables" tabindex="-1">Show Data tables <a class="header-anchor" href="#show-data-tables" aria-label="Permalink to &quot;Show Data tables&quot;">​</a></h3><p>This feature is extremely useful if you calibrate using the xDrip algorithm (non-native).<br> It will add two entries in the drawer menu for visualization of calibration and data tables.</p><div class="admonition xdripitem"><p class="admonition-title">Show Data tables <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show Calibration and BG data tables in the app drawer.</p></div><p><em>Note: Calibration graph will not show in native mode.</em></p><h3 id="display-bridge-battery" tabindex="-1">Display Bridge Battery <a class="header-anchor" href="#display-bridge-battery" aria-label="Permalink to &quot;Display Bridge Battery&quot;">​</a></h3><p>You can display your Bluetooth bridge battery level on the main view. This also applies to Libre Bluetooth bridges.<br> In follower mode it will most probably display the master phone battery level rather than the bridge itself.</p><div class="admonition xdripitem"><p class="admonition-title">Display Bridge Battery <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Choose to display the bridge battery level</p></div><img src="'+l+'" style="zoom:75%;"><h3 id="disable-battery-warning" tabindex="-1">Disable Battery Warning <a class="header-anchor" href="#disable-battery-warning" aria-label="Permalink to &quot;Disable Battery Warning&quot;">​</a></h3><p>Disable battery warnings for bridges</p><div class="admonition xdripitem"><p class="admonition-title">Disable Battery Warning <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Disable the warning for low transmitter battery state on the home screen. (Only relevant for DIY receivers.)</p></div><h3 id="database-automatic-maintenance" tabindex="-1">Database automatic maintenance <a class="header-anchor" href="#database-automatic-maintenance" aria-label="Permalink to &quot;Database automatic maintenance&quot;">​</a></h3><p>Save Database Daily will actually export the database file every day before doing cleanup. This will use a large amount of your device memory and is not recommended.</p><p>Database exports will be saved in the same folder as manual exports: <code>/storage/emulated/0/xDrip</code> or <code>Internal Storage/xDrip</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Save Database Daily <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Allows the daily intent service to save the database before purging</p></div><h4 id="glucose-retention" tabindex="-1">Glucose retention <a class="header-anchor" href="#glucose-retention" aria-label="Permalink to &quot;Glucose retention&quot;">​</a></h4><p>Glucose retention will automatically delete data older than the number of days selected.<br> Zero means don&#39;t delete anything. The shipped default is 180 days, so fresh installs auto-delete data older than 180 days unless you change this. You can use 90 days if you use a cloud backup like Nightscout, so that you will still have all statistics available in xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Glucose retention</p><p> Erase data older than this many days. Setting 0 will keep all data, but xDrip should not be used as a repository — use Nightscout or Tidepool for long-term storage.</p></div><h3 id="other-miscellaneous-options" tabindex="-1"><a href="./misc.html">Other Miscellaneous Options</a> <a class="header-anchor" href="#other-miscellaneous-options" aria-label="Permalink to &quot;[Other Miscellaneous Options](./misc)&quot;">​</a></h3><p>See the dedicated section.</p><div class="admonition xdripitem"><p class="admonition-title">Other misc. options</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',86)])])}const k=r(c,[["render",h]]);export{z as __pageData,k as default};
